<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { api } from '@/api'; import type { Account, BudgetSpace, AccountType } from '@/types'
const accounts = ref<Account[]>([]), spaces = ref<BudgetSpace[]>([]), saved = ref(''); const form = ref<{name:string;budgetSpaceId:string;type:AccountType;openingBalance:number}>({ name:'', budgetSpaceId:'', type:'bank', openingBalance:0 })
const money=(v:number)=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN'}).format(v)
async function load(){ [accounts.value,spaces.value]=await Promise.all([api.accounts(),api.spaces()]); if(!form.value.budgetSpaceId) form.value.budgetSpaceId=spaces.value[0]?.id??'' }
async function save(){ await api.createAccount(form.value); saved.value='Konto zostało utworzone.'; form.value={name:'',budgetSpaceId:form.value.budgetSpaceId,type:'bank',openingBalance:0}; await load() }
onMounted(load)
</script>
<template><div class="grid two wide-first"><section class="panel"><div class="panel-title"><h2>Aktywne konta</h2><span>{{ accounts.length }} kont</span></div><div class="account-row" v-for="a in accounts" :key="a.id"><span class="account-icon">▣</span><span>{{ a.name }}<small>{{ a.type }}</small></span><strong>{{ money(a.balance) }}</strong></div><p v-if="!accounts.length" class="empty">Nie masz jeszcze kont.</p></section><section class="panel"><h2>Nowe konto</h2><form @submit.prevent="save"><label>Nazwa<input v-model.trim="form.name" required placeholder="np. Konto osobiste"/></label><label>Portfel<select v-model="form.budgetSpaceId" required><option v-for="s in spaces" :value="s.id" :key="s.id">{{s.name}}</option></select></label><label>Typ<select v-model="form.type"><option value="cash">Gotówkowe</option><option value="bank">Bankowe</option><option value="savings">Oszczędnościowe</option><option value="deposit">Lokata</option><option value="investment">Inwestycyjne</option><option value="liability">Zobowiązanie</option></select></label><label>Saldo otwarcia<input v-model.number="form.openingBalance" type="number" step="0.01"/></label><button class="button primary">Dodaj konto</button><p class="success" v-if="saved">{{saved}}</p></form></section></div></template>
